const data = window.EXAM_DATA;
const groups = data.labels.map(([from, to, name]) => ({ from, to, name, questions: data.questions.filter(q => q.no >= from && q.no <= to) }));
const key = 'tfs4-2025-prototype-session';
const archiveKey = 'tfs4-2025-prototype-archive';
let session = JSON.parse(localStorage.getItem(key) || 'null') || { answers: {}, startedAt: Date.now(), activeSeconds: 0, lastTick: Date.now(), started: false };
let page = 0;
const $ = s => document.querySelector(s);
const duration = () => session.activeSeconds + (session.started ? Math.floor((Date.now() - session.lastTick) / 1000) : 0);
const fmt = n => [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(x=>String(x).padStart(2,'0')).join(':');
const save = () => localStorage.setItem(key, JSON.stringify({...session, activeSeconds: duration(), lastTick: Date.now()}));
function render() {
  const group = groups[page]; $('#group-name').textContent = group.name; $('#page-title').textContent = `第 ${group.from}–${group.to} 题`;
  const answered = Object.values(session.answers).filter(a => a.choice).length; $('#answered-count').textContent = answered;
  $('#page-dots').innerHTML = groups.map((g,i) => `<button class="${i===page?'active':''} ${g.questions.every(q=>session.answers[q.no]?.choice)?'done':''}" data-page="${i}" aria-label="第 ${g.from} 到 ${g.to} 题">${i+1}</button>`).join('');
  $('#questions').innerHTML = group.questions.map(q => `<article class="question" data-no="${q.no}"><div class="q-top"><span class="q-no">${q.no}</span><span class="q-group">${q.group}</span></div><h3>${escapeHTML(q.text)}</h3><div class="option-list">${Object.keys(q.options).map(letter => `<button class="option ${session.answers[q.no]?.choice===letter?'selected':''}" data-choice="${letter}"><b>${letter}</b><span>${escapeHTML(q.options[letter])}</span></button>`).join('')}</div><div class="confidence"><span>这题把握：</span>${[['肯定','🟢'],['犹豫','🟡'],['猜测','🔴']].map(([v,icon])=>`<button data-confidence="${v}" class="${session.answers[q.no]?.confidence===v?'selected':''}">${icon} ${v}</button>`).join('')}</div></article>`).join('');
  $('#prev').disabled = page === 0; $('#next').textContent = page === groups.length-1 ? '返回第一组 ↺' : '下一组 →';
  $('#page-dots').querySelectorAll('button').forEach(b => b.onclick=()=>{page=Number(b.dataset.page);render();window.scrollTo({top:0,behavior:'smooth'})});
  $('#questions').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(b));
}
function escapeHTML(v=''){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function answer(btn){const card=btn.closest('[data-no]'), no=card.dataset.no; const old=session.answers[no]||{};session.answers[no]={...old,firstAnsweredAt:old.firstAnsweredAt||duration(),lastChangedAt:duration()};if(btn.dataset.choice)session.answers[no].choice=btn.dataset.choice;if(btn.dataset.confidence)session.answers[no].confidence=btn.dataset.confidence;save();render();}
function start(){session.started=true;session.lastTick=Date.now();save();$('#welcome').hidden=true;$('#history').hidden=true;$('#exam').hidden=false;render();}
function showHistory(){session.started=false;save();$('#welcome').hidden=true;$('#exam').hidden=true;$('#history').hidden=false;const rows=JSON.parse(localStorage.getItem(archiveKey)||'[]');$('#history-list').innerHTML=rows.length?rows.map(r=>`<article class="history-card"><div><b>${new Date(r.submittedAt).toLocaleString('zh-CN',{hour12:false})}</b><p>用时 ${fmt(r.duration)} · 已答 ${r.answered}/100 · 肯定 ${r.confidence.肯定||0}</p></div><strong>${r.score}<small> / 100</small></strong></article>`).join(''):'<p class="empty">还没有已交卷的考试记录。</p>';}
function submit(){const answered=Object.values(session.answers).filter(a=>a.choice).length;if(!confirm(`已作答 ${answered}/100 题。提交后，本次记录会保存到本机。确定交卷吗？`))return;const choices=Object.entries(session.answers);const score=choices.filter(([no,a])=>a.choice===data.questions.find(q=>q.no===Number(no))?.answer).length;const confidence=Object.values(session.answers).reduce((o,a)=>(a.confidence&&(o[a.confidence]=(o[a.confidence]||0)+1),o),{});const record={submittedAt:Date.now(),duration:duration(),answered,score,confidence,answers:session.answers};const rows=JSON.parse(localStorage.getItem(archiveKey)||'[]');rows.unshift(record);localStorage.setItem(archiveKey,JSON.stringify(rows));$('#result-content').innerHTML=`<p class="kicker">本次选择题成绩</p><div class="score">${score}<small> / 100</small></div><p class="result-copy">本次答题与用时已保存到本机。第 55、62、100 题使用的是待复核工作答案，不建议据此做精确判断。</p><div class="result-grid"><div><b>${fmt(record.duration)}</b>总用时</div><div><b>${answered}</b>已作答</div><div><b>${confidence.肯定||0}</b>肯定</div></div>`;$('#result').showModal();session={answers:{},startedAt:Date.now(),activeSeconds:0,lastTick:Date.now(),started:false};localStorage.removeItem(key);}
$('#start').onclick=start;$('#open-history').onclick=showHistory;document.querySelector('.back').onclick=()=>{ $('#history').hidden=true; session.started=false; $('#welcome').hidden=false;};$('#prev').onclick=()=>{if(page>0){page--;render();window.scrollTo({top:0,behavior:'smooth'})}};$('#next').onclick=()=>{page=page===groups.length-1?0:page+1;render();window.scrollTo({top:0,behavior:'smooth'})};$('#submit').onclick=submit;$('#result-close').onclick=()=>{$('#result').close();$('#exam').hidden=true;$('#welcome').hidden=false;};setInterval(()=>{$('#clock').textContent=fmt(duration());if(session.started)save()},1000);$('#clock').textContent=fmt(duration());if(session.started)start();
